import type Phaser from "phaser";
import { parseTiledRoom } from "../logic/dungeon/tiled.ts";
import type { RoomTemplate } from "../logic/dungeon/tiled.ts";
import type { TemplateMeta } from "../logic/dungeon/templates.ts";
import catalog from "./roomCatalog.json" with { type: "json" };

/** Generated by `vp run @dh/web#rooms`; the test suite fails when it is stale. */
export const ROOM_CATALOG = catalog as TemplateMeta[];
export const TILESET_KEY = "tiles-s1";
/** Tile ids in tiles-s1.png (firstgid 1). */
export const TILES = { corridorFloor: 2, corridorWall: 3 } as const;

export function queueRoomAssets(load: Phaser.Loader.LoaderPlugin): void {
  load.image(TILESET_KEY, "assets/tilemaps/tiles-s1.png");
  for (const t of ROOM_CATALOG) load.json(`room:${t.id}`, `assets/tilemaps/rooms/${t.id}.json`);
}

export function loadedTemplates(cache: Phaser.Cache.BaseCache): Map<string, RoomTemplate> {
  return new Map(ROOM_CATALOG.map((t) => [t.id, parseTiledRoom(cache.get(`room:${t.id}`), t.id)]));
}
